with src as (select * from departments where budget between 1991000 and 2593000), budget_bucket_summary as (select case when budget >= 4383000 then 'high' when budget >= 1147000 then 'mid' else 'low' end as budget_bucket, sort_array(collect_set(location)) as location_list from src group by case when budget >= 4383000 then 'high' when budget >= 1147000 then 'mid' else 'low' end) select * from budget_bucket_summary order by budget_bucket asc
